190	/**
191	 * Returns a copy of `turns` where `announcement` has been prepended to the
192	 * first top-level assistant turn's first markdown response part. Used on
193	 * session restore so the worktree announcement remains visible after the
194	 * session is reopened. If no assistant content exists yet, a fresh
195	 * markdown part is inserted at the top of the first turn.
196	 */
197	function prependAnnouncementToFirstTurn(
198		turns: readonly Turn[],
199		announcement: string,
200	): readonly Turn[] {
201		if (turns.length === 0) {
202			return turns;
203		}
204		const result = turns.slice();
205		const first = result[0];
206		const partIdx = first.responseParts.findIndex(rp => rp.kind === ResponsePartKind.Markdown);
207		if (partIdx >= 0) {
208			const part = first.responseParts[partIdx];
209			const updated: ResponsePart = part.kind === ResponsePartKind.Markdown
210				? { ...part, content: announcement + part.content }
211				: part;
212			const responseParts = first.responseParts.slice();
213			responseParts[partIdx] = updated;
214			result[0] = { ...first, responseParts };
215		} else {
216			const responseParts: ResponsePart[] = [
217				{ kind: ResponsePartKind.Markdown, id: generateUuid(), content: announcement },
218				...first.responseParts,
219			];
220			result[0] = { ...first, responseParts };
221		}
222		return result;
